{"code":"import json, math
from pathlib import Path
p=Path('/root/oncocooler_analysis.json')
data=json.loads(p.read_text())
expected_top=['assumptions','programs','totals','recommendation']
expected_assumptions={
 'dispatches_per_year_10_day':36,
 'dispatches_per_year_20_day':18,
 'days_per_dispatch_10_day':10,
 'days_per_dispatch_20_day':20,
 'switch_threshold_usd':10000,
 'site_override_rule':'highest approved version_no per program_code, else default_active_sites'
}
expected_program_keys=[
 'program_code','program_name','active_sites','acquisition_cost_per_1000_units_usd','units_per_day','cooler_type','cooler_cost_usd','payment_per_dispatch_per_site_usd','annual_drug_cost_10_day_usd','annual_drug_cost_20_day_usd','annual_cooler_cost_10_day_usd','annual_cooler_cost_20_day_usd','annual_revenue_10_day_usd','annual_revenue_20_day_usd','annual_margin_10_day_usd','annual_margin_20_day_usd','annual_margin_difference_20_minus_10_usd'
]
expected_totals=['total_annual_margin_10_day_usd','total_annual_margin_20_day_usd','total_annual_margin_difference_20_minus_10_usd','absolute_total_margin_difference_usd']
expected_rec=['decision','justification']
errors=[]
if list(data.keys())!=expected_top: errors.append(f'top keys {list(data.keys())}')
if data.get('assumptions')!=expected_assumptions: errors.append('assumptions mismatch')
codes=[r['program_code'] for r in data['programs']]
if codes!=sorted(codes): errors.append('programs not sorted')
for i,r in enumerate(data['programs']):
    if list(r.keys())!=expected_program_keys: errors.append(f'program {i} keys mismatch {list(r.keys())}')
    for days,dispatches,suffix in [(10,36,'10_day'),(20,18,'20_day')]:
        cooler=round(r['cooler_cost_usd']*r['active_sites']*dispatches,2)
        drug=round(r['acquisition_cost_per_1000_units_usd']*r['active_sites']*r['units_per_day']*days*dispatches/1000,2)
        revenue=round(r['payment_per_dispatch_per_site_usd']*r['active_sites']*dispatches,2)
        margin=round(revenue-drug-cooler,2)
        if not math.isclose(r[f'annual_cooler_cost_{suffix}_usd'],cooler,abs_tol=0.001): errors.append(f'{r["program_code"]} cooler {suffix}')
        if not math.isclose(r[f'annual_drug_cost_{suffix}_usd'],drug,abs_tol=0.001): errors.append(f'{r["program_code"]} drug {suffix}')
        if not math.isclose(r[f'annual_revenue_{suffix}_usd'],revenue,abs_tol=0.001): errors.append(f'{r["program_code"]} revenue {suffix}')
        if not math.isclose(r[f'annual_margin_{suffix}_usd'],margin,abs_tol=0.001): errors.append(f'{r["program_code"]} margin {suffix}')
    if not math.isclose(r['annual_margin_difference_20_minus_10_usd'],round(r['annual_margin_20_day_usd']-r['annual_margin_10_day_usd'],2),abs_tol=0.001): errors.append(f'{r["program_code"]} diff')
if list(data['totals'].keys())!=expected_totals: errors.append(f'totals keys {list(data["totals"].keys())}')
if list(data['recommendation'].keys())!=expected_rec: errors.append(f'rec keys {list(data["recommendation"].keys())}')
lines=[line for line in Path('/root/oncocooler_summary.md').read_text().splitlines() if line.strip()]
if not (4<=len(lines)<=8): errors.append(f'summary non-empty lines {len(lines)}')
for phrase in ['Total 10-day margin (USD)','Total 20-day margin (USD)','Absolute difference (USD)','move_to_20_day']:
    if phrase not in '\n'.join(lines): errors.append(f'summary missing {phrase}')
first=data['programs'][0]
print('validation_errors:', errors)
print('program_codes:', codes)
print('summary_nonempty_lines:', len(lines))
print('first_program_spot_check:', first['program_code'])
print('cooler_10:', first['annual_cooler_cost_10_day_usd'], '=', first['cooler_cost_usd'], '*', first['active_sites'], '* 36')
print('cooler_20:', first['annual_cooler_cost_20_day_usd'], '=', first['cooler_cost_usd'], '*', first['active_sites'], '* 18')
print('drug_10:', first['annual_drug_cost_10_day_usd'], '=', first['acquisition_cost_per_1000_units_usd'], '*', first['active_sites'], '*', first['units_per_day'], '* 10 * 36 / 1000')
print('revenue_10:', first['annual_revenue_10_day_usd'], '=', first['payment_per_dispatch_per_site_usd'], '*', first['active_sites'], '* 36')
print('margin_10:', first['annual_margin_10_day_usd'], '=', first['annual_revenue_10_day_usd'], '-', first['annual_drug_cost_10_day_usd'], '-', first['annual_cooler_cost_10_day_usd'])
raise SystemExit(1 if errors else 0)"}
